<?php $this->assign('title', 'Sitios | CatOps Admin'); ?>
<div class="d-flex justify-content-between gap-3 mb-4 page-heading"><div><h1 class="h2 mb-1">Sitios</h1><p class="text-muted mb-0"><?= (int)$pagination['total'] ?> resultados.</p></div></div>
<section class="card admin-card mb-4"><div class="card-body"><form class="row g-2" method="get"><div class="col-12 col-md-6"><input class="form-control" name="q" value="<?= h($filters['q']) ?>" placeholder="Nombre, subdominio o correo del propietario"></div><div class="col-6 col-md-2"><select class="form-select" name="status"><option value="">Estado</option><?php foreach (['draft', 'published', 'paused'] as $status): ?><option value="<?= $status ?>" <?= $filters['status'] === $status ? 'selected' : '' ?>><?= $status ?></option><?php endforeach; ?></select></div><div class="col-6 col-md-3"><select class="form-select" name="template"><option value="">Plantilla</option><?php foreach ($templates as $id => $name): ?><option value="<?= (int)$id ?>" <?= $filters['template'] === (string)$id ? 'selected' : '' ?>><?= h($name) ?></option><?php endforeach; ?></select></div><div class="col-12 col-md-1"><button class="btn btn-primary w-100">Buscar</button></div></form></div></section>
<section class="card admin-card"><div class="table-wrap"><table class="table align-middle"><thead><tr><th>Sitio</th><th>Propietario</th><th>Tipo</th><th>Estado</th><th>Publicación</th><th></th></tr></thead><tbody><?php foreach ($pagination['items'] as $site): ?><tr><td><strong><?= h($site->name) ?></strong><small class="d-block text-muted"><?= h($site->subdomain) ?></small></td><td><?= h($site->user->email ?? '') ?></td><td><?= h($site->template->name ?? '') ?></td><td><span class="badge text-bg-<?= $site->status === 'published' ? 'success' : ($site->status === 'paused' ? 'warning' : 'secondary') ?> badge-status"><?= h($site->status) ?></span></td><td><?= h($site->published_at ?: '—') ?></td><td><a class="btn btn-sm btn-outline-primary" href="/admin/sites/<?= (int)$site->id ?>">Ver</a></td></tr><?php endforeach; ?></tbody></table></div><div class="card-body"><?= $this->element('admin_pagination', compact('pagination')) ?></div></section>
